int H, W, K;
char grid[25][25];

int main() {
    scanf("%d %d %d", &H, &W, &K);
    for (int i = 0; i < H; i++) {
        scanf("%s", grid[i]);
    }

    long long ans = 0;

    // Iterate over all subsets of rows to KEEP (not paint)
    for (int rmask = 0; rmask < (1 << H); rmask++) {
        // For each column, count black squares in kept rows
        int cnt[20];
        for (int j = 0; j < W; j++) {
            cnt[j] = 0;
            for (int i = 0; i < H; i++) {
                if ((rmask >> i) & 1) {
                    if (grid[i][j] == '#') cnt[j]++;
                }
            }
        }

        // DP: count subsets of columns to keep with sum = K
        // dp[s] = number of ways to get sum s from first columns processed
        long long dp[401];
        memset(dp, 0, sizeof(dp));
        dp[0] = 1;

        for (int j = 0; j < W; j++) {
            // Either keep column j (add cnt[j]) or paint it (add 0)
            // We go backwards to avoid using same column twice
            for (int s = K; s >= cnt[j]; s--) {
                dp[s] += dp[s - cnt[j]];
            }
        }

        ans += dp[K];
    }

    printf("%lld\n", ans);
    return 0;
}

