import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        char[][] grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        long answer = 0;

        // Enumerate all subsets of rows to NOT paint (active rows)
        for (int rowMask = 0; rowMask < (1 << H); rowMask++) {
            // For each column, count black squares in active rows
            int[] colCount = new int[W];
            for (int j = 0; j < W; j++) {
                for (int i = 0; i < H; i++) {
                    if ((rowMask & (1 << i)) != 0 && grid[i][j] == '#') {
                        colCount[j]++;
                    }
                }
            }

            // Count subsets of columns (not painted) where sum = K
            // dp[s] = number of column subsets with sum s
            long[] dp = new long[K + 1];
            dp[0] = 1;
            for (int j = 0; j < W; j++) {
                // Each column is either painted (contributes 0) or not painted (contributes colCount[j])
                if (colCount[j] == 0) {
                    // Not painting this column contributes 0, so multiply by 2
                    for (int s = 0; s <= K; s++) {
                        dp[s] *= 2;
                    }
                } else {
                    // Painting: no change; Not painting: add colCount[j]
                    for (int s = K; s >= colCount[j]; s--) {
                        dp[s] += dp[s - colCount[j]];
                    }
                }
            }

            answer += dp[K];
        }

        System.out.println(answer);
    }
}

