        }

        int answer = 0;

        for (int rowMask = 0; rowMask < (1 << H); rowMask++) {
            for (int colMask = 0; colMask < (1 << W); colMask++) {
                int count = 0;

                for (int i = 0; i < H; i++) {
                    if (((rowMask >> i) & 1) == 1) continue; // painted row
                    for (int j = 0; j < W; j++) {
                        if (((colMask >> j) & 1) == 1) continue; // painted column
                        if (grid[i][j] == '#') count++;
                    }
                }

                if (count == K) answer++;
            }
        }

        System.out.println(answer);
    }
}

