            for i in range(H):
                if (rmask >> i) & 1:
                    continue
                for j in range(W):
                    if (cmask >> j) & 1:
                        continue
                    if grid[i][j] == '#':
                        black += 1
            if black == K:
                ans += 1

    print(ans)

